export function operationTags(tenantId, operationId, name) {
  return [
    { Key: 'Name', Value: name },
    { Key: 'TenantId', Value: tenantId },
    { Key: 'ManagedBy', Value: 'vpnconfig-lambda' },
    { Key: 'OperationId', Value: operationId },
  ];
}

export function eipAllocationRequest(tenantId, operationId) {
  return {
    Domain: 'vpc',
    TagSpecifications: [{
      ResourceType: 'elastic-ip',
      Tags: operationTags(
        tenantId,
        operationId,
        `dedicated-ip-eip-${tenantId}`,
      ),
    }],
  };
}

export function selectAvailabilityZoneName(subnets, region) {
  const availabilityZones = (subnets || [])
    .map(subnet => subnet.AvailabilityZone)
    .filter(Boolean)
    .sort();
  return availabilityZones[0] || `${region}a`;
}

export function assertCidrOwnership(allocations, index, tenantId) {
  const currentOwner = allocations[String(index)];
  if (currentOwner === undefined) return false;
  if (currentOwner !== tenantId) {
    throw new Error(`CIDR allocation ${index} is owned by another tenant`);
  }
  return true;
}

export function canReleaseCidr(remainingResources) {
  return !remainingResources.privateSubnetId
    && !remainingResources.publicSubnetId;
}

export function compactResourceJournal(resources = {}) {
  return Object.fromEntries(
    Object.entries(resources || {})
      .filter(([, value]) => value !== null && value !== undefined),
  );
}

export async function createOptionalResourceWithRequiredCheckpoint({
  create,
  checkpoint,
  onCreateError,
}) {
  try {
    await create();
  } catch (error) {
    onCreateError(error);
    return false;
  }
  await checkpoint();
  return true;
}

export function deriveCidrBase(vpcCidr) {
  const [firstOctet, secondOctet] = vpcCidr.split('.');
  return `${firstOctet}.${secondOctet}`;
}

export function dedicatedSubnetCidrs(vpcCidr, index) {
  const base = deriveCidrBase(vpcCidr);
  return {
    privateCidr: `${base}.${index}.0/26`,
    publicCidr: `${base}.${index}.64/26`,
  };
}

export function selectCidrIndex(
  allocations,
  nextIndex,
  tenantId,
  { startIndex = 10, maxIndex = 255 } = {},
) {
  const existing = Object.entries(allocations)
    .find(([, allocatedTenantId]) => allocatedTenantId === tenantId);
  if (existing) {
    return { index: Number(existing[0]), existing: true };
  }

  let index = nextIndex;
  for (let candidate = startIndex; candidate < nextIndex; candidate++) {
    if (!allocations[String(candidate)]) {
      index = candidate;
      break;
    }
  }
  if (index > maxIndex) {
    throw new Error(
      `VPC CIDR address space exhausted (max ${maxIndex - startIndex + 1} dedicated IPs). Deallocate unused tenants first.`,
    );
  }
  return { index, existing: false };
}
